use ingetrazo_gui::IngeTrazoApp;use ingetrazo_core::scene::SelectionItem;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());for name in ["touching","fragments","names","patches"]{let mut app=IngeTrazoApp::new();app.scene=ingetrazo_formats::igz::load_igz(&dir.join(format!("{name}-source.igz"))).unwrap();app.scene.select(SelectionItem::Group(0));let before=app.scene.clone();let depth=app.undo_stack.len();app.split_into_pieces();assert_eq!(app.undo_stack.len(),depth+1);let split=app.scene.clone();ingetrazo_formats::igz::save_igz(&app.scene,&dir.join(format!("{name}-result.igz"))).unwrap();app.undo();assert_eq!(app.scene,before);app.redo();assert_eq!(app.scene,split);let depth=app.undo_stack.len();app.split_into_pieces();assert_eq!(app.undo_stack.len(),depth);}}
